-- Carga de alumnos de Ravenclaw en Oracle
-- Tabla ALUMNOS ya existente.
-- Se omiten alias, patronus_origen y wiki.
-- Las fechas aproximadas del CSV se convierten a una fecha estimada de tipo DATE.

DROP TABLE IF EXISTS alumnos;

CREATE TABLE alumnos (
    id VARCHAR2(36) PRIMARY KEY,
    nombre VARCHAR2(150) NOT NULL,
    casa VARCHAR2(50) NOT NULL,
    especie VARCHAR2(100),
    genero VARCHAR2(50),
    nacimiento DATE NOT NULL,
    nacionalidad VARCHAR2(150),
    patronus VARCHAR2(150),
    imagen VARCHAR2(1000)
);


COMMIT;
